# ---------- checks + write ----------
for t in T:
    ex = t.get("example", {})
    for q in t["questions"]:
        if q["options"]:
            assert q["answer"] in q["options"] or any(o.startswith(q["answer"] + " ") for o in q["options"]), (t["id"], q["answer"])
    if t["id"].endswith(("reading-1", "use-2")):
        assert ex["answer"] in t["questions"][0]["options"]
        n = t["text_el"].count("["); assert n == len(t["questions"]) + 1, (t["id"], n)
    if t["id"].endswith("use-1"):
        lines = t["text_el"].split("\n")
        for w in [ex["wrong_word"]] + [q["answer"] for q in t["questions"]]:
            hits = [l for l in lines if w in [x.strip(",.:;«»") for x in l.split()]]
            assert len(hits) == 1, (w, hits)
    if t["id"].endswith("use-4"):
        for w in [ex["answer"]] + [q["answer"] for q in t["questions"]]:
            assert w in t["text_el"], w
out = {"description": "Γ1 exam practice, set 220 (Πιστοποίηση Ελληνομάθειας Γ1, ΚΕΓ format), same schema as the c1-p3-* tasks in c1-tasks.json: an article on Athanasios Psalidas, the teacher of Ioannina (gap-fill), a literary extract about a sister's dress (headings), an article on lobsters and the myth of immortality (multiple choice and summary), a text on the composer Pavlos Carrer (error spotting and gap-fill), and Limni in north Euboea (word formation and definitions).",
       "rights": "Tasks c1-p220-*: original texts and items written for this learner (personal study use).", "tasks": T}
p = os.path.join(os.path.dirname(__file__), "..", "..", "library", "exam", "c1-tasks-218.json")
with open(p, "w", encoding="utf-8") as fh:
    json.dump(out, fh, ensure_ascii=False, indent=1); fh.write("\n")
print(len(T), "tasks,", sum(len(t["questions"]) for t in T), "questions")
